const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sanJose = ee.Geometry.Point([-121.89, 37.33]).buffer(20000); // 20km buffer
  const losAngeles = ee.Geometry.Point([-118.24, 34.05]).buffer(20000); // 20km buffer
  const startDate = '2018-01-01';
  const endDate = '2019-12-31';
  const band = 'tropospheric_NO2_column_number_density';

  // 2. Data Acquisition & Processing
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select([band, 'qa_value'])
    .filterDate(startDate, endDate);

  // Use recommended QA value > 0.75 to filter for high-quality pixels
  const qualityMasked = collection.map(function(image) {
    const qa_mask = image.select('qa_value').gt(0.75);
    return image.updateMask(qa_mask);
  });

  const sanJoseCol = qualityMasked.filterBounds(sanJose);
  const losAngelesCol = qualityMasked.filterBounds(losAngeles);

  const sanJoseCount = sanJoseCol.size().getInfo();
  const losAngelesCount = losAngelesCol.size().getInfo();

  if (sanJoseCount === 0 || losAngelesCount === 0) {
    console.log(`San Jose image count: ${sanJoseCount}`);
    console.log(`Los Angeles image count: ${losAngelesCount}`);
    console.log("Empty Collection: No images found for one or both locations.");
    console.log("A"); // C1 is not the answer tag as per requirements
    return;
  }

  // 3. Calculation
  // Create a single mean composite for the entire period
  const meanImage = qualityMasked.select(band).mean();

  const scale = 3000; // Use a larger scale to ensure calculation completes

  const sanJoseStats = meanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: sanJose,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const losAngelesStats = meanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: losAngeles,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const sanJoseVal = sanJoseStats[band + '_mean'];
  const sanJosePixels = sanJoseStats[band + '_count'];

  const losAngelesVal = losAngelesStats[band + '_mean'];
  const losAngelesPixels = losAngelesStats[band + '_count'];

  // 4. Validation & Final Answer
  if (sanJosePixels === 0 || losAngelesPixels === 0) {
      console.log(`San Jose valid pixels: ${sanJosePixels}`);
      console.log(`Los Angeles valid pixels: ${losAngelesPixels}`);
      console.log("No valid pixels after cloud/QA masking for one or both locations.");
      console.log("C2");
      return;
  }

  if (sanJoseVal === null || losAngelesVal === null) {
      console.log("Calculation resulted in null values.");
      console.log("C3");
      return;
  }

  // Values are in mol/m^2. Convert to umol/m^2 for better readability.
  const sj_umol = sanJoseVal * 1e6;
  const la_umol = losAngelesVal * 1e6;

  console.log(`Time Period: ${startDate} to ${endDate}`);
  console.log(`Image count (San Jose): ${sanJoseCount}`);
  console.log(`Image count (Los Angeles): ${losAngelesCount}`);
  console.log(`San Jose Avg NO2 (umol/m^2): ${sj_umol.toFixed(2)} (${sanJosePixels} pixels)`);
  console.log(`Los Angeles Avg NO2 (umol/m^2): ${la_umol.toFixed(2)} (${losAngelesPixels} pixels)`);

  if (sj_umol > la_umol) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
